      try { rr = _rt.leg ? await _runConnectorLeg(_rt.leg, { ..._rt.baseParams, [_rt.valueParam]: results[ri].value }, { tabId, groundId: _rt.groundId , derived: true }) : null; } catch { rr = null; }
