    _setMessageBody(msg, `Swept ${results.length} read${results.length === 1 ? '' : 's'} — ${summary ? 'no actionable proposals.' : 'the queue looks clean.'}${qBlock ? `\n\n${qBlock}` : ''}${summary ? `\n\n${summary}` : ''}`, { markdown: true });
    _orchFinalize(msg);
