  _orchLog(`EXPLORE ▸ chat ask → ground ${g.groundId} (${g.created ? 'minted' : 'reused'}; readiness ${g.readiness || '?'})`);
  _setMessageBody(msg, `Exploring ${host} — this takes a few seconds (I'll poke around the page to map what it offers)…`);
